import Foundation

/// A starter library so suggestions and plans work from day one. Ingredients are written as people write them and go
/// through the same parser as imported recipes, so the parser is exercised by every one of them.
public enum BuiltInRecipes {
    struct Spec {
        let name: String
        let meals: [MealType]
        let serves: Int
        let minutes: Int
        let prep: Bool
        let ingredients: [String]
        let steps: [String]
        let summary: String
    }

    static func id(_ i: Int) -> UUID { UUID(uuidString: String(format: "B0000000-0000-4000-8000-%012d", i))! }

    public static let all: [Recipe] = specs.enumerated().map { i, s in
        Recipe(id: id(i + 1), name: s.name, summary: s.summary, mealTypes: s.meals, servings: s.serves,
               ingredients: s.ingredients.compactMap { IngredientParser.ingredient($0) }, steps: s.steps,
               minutes: s.minutes, tags: [], source: RecipeSource(kind: .builtIn), mealPrepFriendly: s.prep,
               createdAt: Date(timeIntervalSince1970: 1_793_000_000))
    }

    static let specs: [Spec] = [
        // Breakfasts
        Spec(name: "Protein overnight oats", meals: [.breakfast], serves: 1, minutes: 5, prep: true,
             ingredients: ["50g porridge oats", "150ml semi-skimmed milk", "100g greek yoghurt", "1 tbsp chia seeds", "75g frozen berries", "1 tsp honey"],
             steps: ["Stir the oats, milk, yoghurt and chia seeds together in a jar.", "Top with the berries and honey.", "Cover and leave in the fridge overnight."],
             summary: "Made the night before, ready when you are."),
        Spec(name: "Scrambled eggs on toast", meals: [.breakfast], serves: 1, minutes: 10, prep: false,
             ingredients: ["3 eggs", "2 slices wholemeal bread", "10g butter", "1 tbsp milk", "salt and pepper to taste"],
             steps: ["Whisk the eggs with the milk and a pinch of salt and pepper.", "Melt the butter in a pan over a low heat, add the eggs and stir slowly until just set.", "Serve on hot toast."],
             summary: "The classic, done slowly."),
        Spec(name: "Banana protein pancakes", meals: [.breakfast], serves: 1, minutes: 15, prep: false,
             ingredients: ["1 ripe banana", "2 eggs", "40g oats", "30g protein powder", "50g blueberries", "1 tsp honey"],
             steps: ["Blend the banana, eggs, oats and protein powder into a batter.", "Cook small pancakes in a lightly oiled pan, about a minute each side.", "Top with blueberries and honey."],
             summary: "Four ingredients, lots of protein."),
        Spec(name: "Greek yoghurt granola bowl", meals: [.breakfast, .snack], serves: 1, minutes: 3, prep: false,
